  &quot;occurred_at&quot;: &quot;2026-09-07T09:00:00.000Z&quot;,
  &quot;action&quot;: &quot;access.authentication.succeeded&quot;,
  &quot;subject&quot;: {
    &quot;type&quot;: &quot;employee&quot;,
